solution.code:
#include <stdio.h>

#define SIZE 3

int items[SIZE];
int front = 0, count = 0;

void enqueue(int value) {
    items[(front + count) % SIZE] = value;
    count++;
}

int dequeue() {
    int value = items[front];
    front = (front + 1) % SIZE;
    count--;
    return value;
}

int main() {
    enqueue(1);
    enqueue(2);
    enqueue(3);
    printf("%d ", dequeue());
    enqueue(4);
    printf("%d ", dequeue());
    printf("%d ", dequeue());
    printf("%d\n", dequeue());
    return 0;
}
